'use strict';
function missingAltText(images) {
  return images.filter((img) => !img.alt || img.alt.trim() === '').map((img) => img.src);
}
module.exports = { missingAltText };

'use strict';
function relativeLuminance(rgb) {
  const channels = rgb.map((c) => {
    const s = c / 255;
    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * channels[0] + 0.7152 * channels[1] + 0.0722 * channels[2];
}
function contrastRatio(fg, bg) {
  const l1 = relativeLuminance(fg);
  const l2 = relativeLuminance(bg);
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}
module.exports = { relativeLuminance, contrastRatio };

'use strict';
function tabbableOrder(elements) {
  return elements
    .filter((el) => (el.tabIndex || 0) >= 0 && !el.disabled)
    .sort((a, b) => (a.tabIndex || 0) - (b.tabIndex || 0));
}
module.exports = { tabbableOrder };

'use strict';
const BREAKPOINTS = [
  { name: 'mobile', max: 640 },
  { name: 'tablet', max: 1024 },
  { name: 'desktop', max: Infinity },
];
function resolveBreakpoint(width) {
  return (BREAKPOINTS.find((b) => width <= b.max) || BREAKPOINTS[BREAKPOINTS.length - 1]).name;
}
module.exports = { resolveBreakpoint, BREAKPOINTS };

'use strict';
function loadingState(elapsedMs, thresholds) {
  const t = thresholds || { skeleton: 200, spinner: 1000 };
  if (elapsedMs < t.skeleton) return 'idle';
  if (elapsedMs < t.spinner) return 'skeleton';
  return 'spinner';
}
module.exports = { loadingState };
